const router = Router();

interface Alert {
  sensorId: number;
  warehouseId: number;
  alertType: 'missed_heartbeat' | 'out_of_range';
}

function checkHeartbeat(sensorId: number, warehouseId: number): boolean {
  const latestReading = getLatestReadingByWarehouse(warehouseId);
  if (!latestReading) return true;
  const currentTime = Date.now();
  const heartbeatInterval = 60 * 1000; // 1 minute
  return currentTime - latestReading.timestamp > heartbeatInterval;
}

function checkRange(sensorId: number, warehouseId: number): boolean {
  const readings = getReadingsBySensor(sensorId);
  if (readings.length === 0) return true;
  const minValue = Math.min(...readings.map(r => r.value));
  const maxValue = Math.max(...readings.map(r => r.value));
  const rangeThreshold = 50; // Example threshold
  return minValue < rangeThreshold || maxValue > rangeThreshold;
}

router.post("/:sensorId", middleware, async (req: Request, res: Response) => {
  const sensorId = Number(req.params.sensorId);
  const warehouseId = Number(req.body.warehouseId);
  const device = getDeviceById(sensorId);

  if (!device) {
    return res.status(404).json({ error: "Device not found" });
  }

  const alerts: Alert[] = [];

  if (checkHeartbeat(sensorId, warehouseId)) {
    alerts.push({ sensorId, warehouseId, alertType: 'missed_heartbeat' });
  }

  if (checkRange(sensorId, warehouseId)) {
    alerts.push({ sensorId, warehouseId, alertType: 'out_of_range' });
  }

  if (alerts.length > 0) {
    return res.status(200).json(alerts);
  } else {
    return res.status(200).json({ message: "No alerts" });
