import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-sensitive routes
  if (req.method === "GET" && !req.path.startsWith("/session-notes")) {
    return next();
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    return res.status(401).send("Unauthorized: JWT secret is not set");
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return res.status(401).send("Unauthorized: Missing or invalid authorization header");
  }

  const token = authHeader.split(" ")[1];
  try {
    const crypto = require("node:crypto");
    const hmac = crypto.createHmac("sha256", jwtSecret);
    hmac.update(token);
    const digest = hmac.digest("hex");

    if (crypto.timingSafeEqual(Buffer.from(digest), Buffer.from(token))) {
      return next();
    } else {
      return res.status(403).send("Forbidden: Invalid token");
    }
  } catch (error) {
    return res.status(500).send("Internal Server Error");
  }
}

