interface WeeklyHours {
  employeeId: number;
  totalHours: number;
}

function calculateWeeklyHours(clockEvents: ClockEvent[]): WeeklyHours[] {
  const hoursMap: { [employeeId: number]: number } = {};

  clockEvents.forEach(event => {
    const employeeId = event.employeeId;
    const timestamp = new Date(event.timestamp);
    const hour = timestamp.getHours() + timestamp.getMinutes() / 60;

    if (!hoursMap[employeeId]) {
      hoursMap[employeeId] = 0;
    }

    if (event.eventType === 'in') {
      hoursMap[employeeId] += hour;
    } else if (event.eventType === 'out') {
      hoursMap[employeeId] -= hour;
    }
  });

  return Object.keys(hoursMap).map(employeeId => ({
    employeeId: parseInt(employeeId),
    totalHours: Math.abs(hoursMap[employeeId])
  }));
}

