import type { Request, Response, NextFunction } from "express";

export function middleware(req: Request, res: Response, next: NextFunction): void {
  // Skip validation for non-POST requests to /api/payroll/export
  if (req.method !== "POST" || !req.path.startsWith("/api/payroll/export")) {
    next();
    return;
  }

  const jwtSecret = process.env.JWT_SECRET;
  if (!jwtSecret) {
    res.status(401).send("Unauthorized: JWT secret is not set");
    return;
  }

  const authHeader = req.headers["authorization"];
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).send("Unauthorized: Missing or invalid Bearer token");
    return;
  }

  const token = authHeader.split(" ")[1];

  try {
    const crypto = require("node:crypto");
    const hmac = crypto.createHmac("sha256", jwtSecret);
    hmac.update(token);
    const expectedSignature = hmac.digest("hex");

    const [header, payload, signature] = token.split(".");
    const decodedSignature = Buffer.from(signature, "base64").toString("utf8");

    if (crypto.timingSafeEqual(Buffer.from(expectedSignature), Buffer.from(decodedSignature))) {
      next();
    } else {
      res.status(403).send("Forbidden: Invalid token signature");
    }
  } catch (error) {
    res.status(401).send("Unauthorized: Error processing token");
  }
}

